INSERT OR IGNORE INTO video_skills VALUES(
 'automotive-review','Обзор · ведущий и детали','Вертикальные обзоры с двухстрочными титрами и обложкой',
 'Создавай обзор только из загруженных пользователем исходников. Сохраняй речь ведущего: originalAudio=true, speed=1 на разговорных сценах. Чередуй общий план и детали, только если пользователь явно описал содержание файлов. Не выдумывай анализ кадров. Названия моделей и факты бери из задания. Сцены: textStyle=review, title короткое название, subtitle краткое пояснение, titleY=58, titleScale=6, titleStart=0, titleDuration длительность сцены, motion=none на речи. Переход cut, иногда короткий fade на деталях. Не используй одинаковый начальный фрагмент по кругу. Верни cover style=automotive с конкретным заголовком без выдуманных цен. Субтитры речи только по предоставленным таймкодам, иначе cues=[] и captionsEnabled=false. Возвращай JSON VMET, а не код или shell.',
 1,'lite','builtin:automotive-review','4bb6a29268055e1ce714b9084875e062bb51c5ff','2026-11-17T00:00:00.000Z'
);
